Constants `CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT` and `CONST.TRANSACTION.DEFAULT_MERCHANT` are accessed on every iteration but don't depend on the transaction. These should be hoisted outside the callback to avoid redundant constant access.

```tsx
const PARTIAL_MERCHANT = CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT;
const DEFAULT_MERCHANT = CONST.TRANSACTION.DEFAULT_MERCHANT;

const filteredData = useMemo(() => {
    if (\!debouncedSearchValue.trim() || \!shouldShowTextInput) {
        return data;
    }
    return tokenizedSearch(data, debouncedSearchValue, (transaction) => {
        const searchableFields: string[] = [];
        const merchant = getMerchant(transaction);
        if (merchant \!== PARTIAL_MERCHANT && merchant \!== DEFAULT_MERCHANT) {
            searchableFields.push(merchant);
        }
        // ... rest of logic
    });
}, [data, debouncedSearchValue, shouldShowTextInput]);
```

